from pathlib import Path
import subprocess,os,signal
repo=Path('/Users/steventran/jobpipe')
base='b8a787b5b6c9df5bda03db4b5c9f3da67d80317a'
target=repo/'tools/ats_field_labels.py'
test=repo/'tests/test_ats_field_labels.py'
def git(*args):
 return subprocess.run(['git',*args],cwd=repo,check=True,capture_output=True,text=True).stdout.strip()
if git('rev-parse','HEAD')!=base or git('rev-parse','origin/main')!=base:raise SystemExit('AUTHORITY_CHANGED')
if target.exists() or test.exists():raise SystemExit('TARGETS_ALREADY_EXIST')
target.write_text('''"""Extract browser-visible question context for public ATS controls; never read values."""
from __future__ import annotations

# Evaluation reads labels and nearby question text only, never field values.
_FIELD_SCRIPT = r"""els => els.filter(e => !['hidden', 'password'].includes((e.type||'').toLowerCase())).map(e => {
  const clean = s => (s||'').replace(/\\\\s+/g,' ').trim().slice(0,240);
  const direct = clean((e.labels && Array.from(e.labels).map(l=>l.innerText).join(' ')) || e.getAttribute('aria-label') || '');
  const referenced = (e.getAttribute('aria-labelledby')||'').split(/\\\\s+/).map(id => document.getElementById(id)).filter(Boolean).map(x=>x.innerText).join(' ');
  const group = e.closest('fieldset,[role="group"],[role="radiogroup"]');
  const legend = group && group.querySelector('legend,[role="heading"],[data-question]');
  const question = clean(referenced || (legend && legend.innerText) || '');
  return {type:(e.type||e.tagName).toLowerCase(), required:!!e.required || e.getAttribute('aria-required')==='true',
    label:direct,question:question,ambiguous:!question && (!direct || /^(yes|no)$/i.test(direct))};
})"""

async def extract_field_labels(page):
    """Read-only field metadata. Ambiguous Yes/No never becomes its own question."""
    return await page.locator("input,select,textarea").evaluate_all(_FIELD_SCRIPT)
''')
test.write_text('''"""Isolated browser fixture: question context must not be invented."""
import pytest
from tools.ats_field_labels import extract_field_labels

@pytest.mark.asyncio
async def test_grouped_yes_no_and_unlabeled_fields():
    from playwright.async_api import async_playwright
    async with async_playwright() as pw:
        browser=await pw.chromium.launch(headless=True)
        try:
            page=await browser.new_page()
            await page.set_content("""<form>
              <fieldset><legend>Will you require sponsorship?</legend>
                <label><input type="radio" name="sponsor" required>Yes</label>
                <label><input type="radio" name="sponsor">No</label>
              </fieldset>
              <label for="mail">Email</label><input id="mail" type="email" required>
              <input type="checkbox" aria-label="Yes" required>
              <input type="hidden" value="private-secret">
              </form>""")
            fields=await extract_field_labels(page)
            assert len(fields)==4
            assert fields[0]["question"]=="Will you require sponsorship?"
            assert fields[0]["label"]=="Yes" and not fields[0]["ambiguous"]
            assert fields[1]["question"]=="Will you require sponsorship?"
            assert fields[2]["label"]=="Email" and not fields[2]["ambiguous"]
            assert fields[3]["ambiguous"] and fields[3]["question"]==""
            assert "private-secret" not in str(fields)
        finally:
            await browser.close()
''')
